#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .01

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdCapsule(vec3 p, vec3 a, vec3 b, float r) {
    vec3 ab = b - a;
    vec3 ap = p - a;
    float t = clamp(dot(ap, ab) / dot(ab, ab), 0., 1.);
    vec3 c = a + t * ab;
    return length(p - c) - r;
}

float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

vec3 applyWobble(vec3 p, float time) {
    float wobbleFreq = 3.0;
    float wobbleAmp = 0.09; //rumprobieren
    p.x += sin(p.y * wobbleFreq + time) * wobbleAmp;
    p.z += cos(p.y * wobbleFreq + time) * wobbleAmp;
    return p;
}

float getSceneDistance(vec3 p) {
    float time = iTime * 2.;

    // wobble wobble
    p = applyWobble(p, time);

    // Body
    float d = sdCapsule(p, vec3(0, 0.5, 0), vec3(0, 2, 0), 0.5);

    // Hhead
    d = smin(d, sdSphere(p - vec3(0, 2.5, 0), 0.5), 0.2);

    // legs
    d = smin(d, sdCapsule(p, vec3(-0.3, 0, 0), vec3(-0.3, 1, 0), 0.2), 0.1);
    d = smin(d, sdCapsule(p, vec3(0.3, 0, 0), vec3(0.3, 1, 0), 0.2), 0.1);

    // arms 
    float upperArmSwing = -1.0+ sin(time*0.5) * 0.5; //-1.0 weiter oben
    float lowerArmSwing = sin(time * 0.9) * 1.6;

    vec3 leftShoulderJoint = vec3(-0.5, 2.0, 0);
    vec3 rightShoulderJoint = vec3(0.5, 2.0, 0);

    // Left arm
    vec3 leftElbowJoint = leftShoulderJoint + vec3(sin(upperArmSwing), -cos(upperArmSwing), 0) * 0.7;
    vec3 leftHandJoint = leftElbowJoint + vec3(sin(lowerArmSwing), -cos(lowerArmSwing), 0) * 0.7;

    d = smin(d, sdCapsule(p, leftShoulderJoint, leftElbowJoint, 0.15), 0.1);
    d = smin(d, sdCapsule(p, leftElbowJoint, leftHandJoint, 0.12), 0.1);

    // Right arm
    vec3 rightElbowJoint = rightShoulderJoint + vec3(-sin(upperArmSwing), -cos(upperArmSwing), 0) * 0.7;
    vec3 rightHandJoint = rightElbowJoint + vec3(-sin(lowerArmSwing), -cos(lowerArmSwing), 0) * 0.7;

    d = smin(d, sdCapsule(p, rightShoulderJoint, rightElbowJoint, 0.15), 0.1);
    d = smin(d, sdCapsule(p, rightElbowJoint, rightHandJoint, 0.12), 0.1);

    // haare
    vec3 headCenter = vec3(0, 2.5, 0);
    float hairSwingFreq = 3.0;
    float hairSwingAmp = 0.2;

    for (int i = 0; i < 16; i++) {
        float angle = float(i) / 4.0 * 3.14159;
        vec3 hairRoot = headCenter + vec3(cos(angle) * 0.4, 0.3, sin(angle) * 0.4);
        vec3 hairTip = hairRoot + vec3(0, 0.3, 0);

        hairTip.x += sin(0.5* time * hairSwingFreq + float(i)) * hairSwingAmp;
        hairTip.z += cos(0.5*time * hairSwingFreq + float(i)) * hairSwingAmp;

        d = smin(d, sdCapsule(p, hairRoot, hairTip, 0.05), 0.1);
    }

    return d;
}

vec3 getRayDirection(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l - p),
         r = normalize(cross(vec3(0, 1, 0), f)),
         u = cross(f, r),
         c = f * z,
         i = c + uv.x * r + uv.y * u;
    return normalize(i);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - .5 * iResolution.xy) / iResolution.y;

    // cam rot
    float time = iTime * 0.5; // slwoer rot
    float radius = 5.0; 
    vec3 ro = vec3(sin(time) * radius, 3, cos(time) * radius);
    vec3 lookAt = vec3(0, 1.5, 0); 

    vec3 rd = getRayDirection(uv, ro, lookAt, 1.);

    float d = 0., t = 0.;
    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * d;
        t = getSceneDistance(p);
        d += t;
        if(t < SURF_DIST || d > MAX_DIST) break;
    }

    vec3 col = vec3(0);
    if(d < MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = normalize(vec3(
            getSceneDistance(p + vec3(0.01, 0, 0)) - getSceneDistance(p - vec3(0.01, 0, 0)),
            getSceneDistance(p + vec3(0, 0.01, 0)) - getSceneDistance(p - vec3(0, 0.01, 0)),
            getSceneDistance(p + vec3(0, 0, 0.01)) - getSceneDistance(p - vec3(0, 0, 0.01))
        ));
        col = n * 0.5 + 0.5;
    }

    fragColor = vec4(col, 1.0);
}
